package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.distribution.NormalDistribution;
import org.apache.commons.math3.analysis.integration.gauss.*;
import org.apache.commons.math3.optim.*;
import org.apache.commons.math3.optim.univariate.*;
import org.apache.commons.math3.optim.nonlinear.scalar.GoalType;

/** Declared ordinal thresholds and pairwise latent-response ML with threshold-adjusted influence. */
public final class Polychoric {
    private Polychoric(){}
    private static final NormalDistribution NORMAL=new NormalDistribution();
    private static final GaussIntegrator QUADRATURE=new GaussIntegratorFactory().legendre(96);
    public record Pair(int first,int second,double correlation,double logLikelihood,boolean boundary,int[][] counts){}
    public record Fit(int observations,List<String> names,List<List<String>> levels,double[][] thresholds,List<Pair> pairs,double[][] correlation,double[][] momentCovariance,List<String> warnings){public Fit{names=List.copyOf(names);levels=levels.stream().map(List::copyOf).toList();thresholds=Matrices.copy(thresholds);pairs=List.copyOf(pairs);correlation=Matrices.copy(correlation);momentCovariance=Matrices.copy(momentCovariance);warnings=List.copyOf(warnings);}}
    public static Fit fit(int[][] codes,List<String> names,List<List<String>> levels,int minimumCategoryCount){
        if(codes==null||codes.length<50||codes.length>10000||names.size()<2||names.size()>16||levels.size()!=names.size()||minimumCategoryCount<1||minimumCategoryCount>100)throw new IllegalArgumentException("Ordinal correlations support 50–10,000 complete rows, 2–16 declared variables and a positive minimum category count.");int n=codes.length,p=names.size();if(new HashSet<>(names).size()!=p)throw new IllegalArgumentException("Ordinal variable identities must be unique.");double[][] thresholds=new double[p][];int[][] marginal=new int[p][];List<String> warnings=new ArrayList<>();
        for(int j=0;j<p;j++){var values=levels.get(j);if(values.size()<2||values.size()>12||new HashSet<>(values).size()!=values.size()||values.stream().anyMatch(v->v==null||v.isBlank()))throw new IllegalArgumentException("Declare 2–12 distinct nonempty ordered levels for "+names.get(j));marginal[j]=new int[values.size()];}
        for(var row:codes){if(row==null||row.length!=p)throw new IllegalArgumentException("Ordinal rows must match the declared variable order.");for(int j=0;j<p;j++){if(row[j]<0||row[j]>=levels.get(j).size())throw new IllegalArgumentException("A category code lies outside its declared ordered levels.");marginal[j][row[j]]++;}}
        for(int j=0;j<p;j++){int sum=0;thresholds[j]=new double[levels.get(j).size()-1];for(int k=0;k<marginal[j].length;k++){if(marginal[j][k]<minimumCategoryCount)throw new IllegalArgumentException(names.get(j)+" / "+levels.get(j).get(k)+" has fewer than "+minimumCategoryCount+" observed cases. No category merging was applied.");if(marginal[j][k]<5)warnings.add("Sparse category: "+names.get(j)+" / "+levels.get(j).get(k)+". Asymptotic ordinal inference needs particular caution.");sum+=marginal[j][k];if(k<thresholds[j].length)thresholds[j][k]=NORMAL.inverseCumulativeProbability(sum/(double)n);}}
        int moments=p*(p-1)/2;double[][] influences=new double[n][moments],correlation=new double[p][p];for(int j=0;j<p;j++)correlation[j][j]=1;List<Pair> pairs=new ArrayList<>();
        for(int a=0;a<p;a++)for(int b=a+1;b<p;b++){
            Matrices.interrupted();int ka=levels.get(a).size(),kb=levels.get(b).size();int[][] counts=new int[ka][kb];for(var row:codes)counts[row[a]][row[b]]++;final int aa=a,bb=b;
            UnivariateFunction objective=new UnivariateFunction(rho->pairLoss(counts,thresholds[aa],thresholds[bb],rho));var optimum=new BrentOptimizer(1e-10,1e-12).optimize(new MaxEval(200),new UnivariateObjectiveFunction(objective::value),GoalType.MINIMIZE,new SearchInterval(-.995,.995,0));double rho=optimum.getPoint();boolean boundary=Math.abs(rho)>.9949;if(boundary)throw new IllegalArgumentException("Ordinal response correlation "+names.get(a)+" / "+names.get(b)+" is at the configured boundary; regular threshold-adjusted inference is unavailable. Review duplicate items or sparse categories.");correlation[a][b]=correlation[b][a]=rho;int column=pairs.size();pairs.add(new Pair(a,b,rho,-optimum.getValue(),false,counts));double[][] score=new double[ka][kb];double information=0;double[] crossA=new double[ka-1],crossB=new double[kb-1];
            for(int i=0;i<ka;i++)for(int j=0;j<kb;j++){double al=bound(thresholds[a],i-1),au=bound(thresholds[a],i),bl=bound(thresholds[b],j-1),bu=bound(thresholds[b],j);double probability=cell(al,au,bl,bu,rho),derivative=density(au,bu,rho)-density(al,bu,rho)-density(au,bl,rho)+density(al,bl,rho);if(probability<1e-14){if(counts[i][j]>0||Math.abs(derivative)>1e-12)throw new IllegalArgumentException("An ordinal cell probability is numerically unresolved; no probability floor was used for inference.");continue;}score[i][j]=derivative/probability;information+=derivative*derivative/probability;for(int k=0;k<ka-1;k++)if(k==i||k==i-1){double t=thresholds[a][k],sign=k==i?1:-1,dp=sign*NORMAL.density(t)*(cdf((bu-rho*t)/Math.sqrt(1-rho*rho))-cdf((bl-rho*t)/Math.sqrt(1-rho*rho)));crossA[k]+=derivative*dp/probability;}for(int k=0;k<kb-1;k++)if(k==j||k==j-1){double t=thresholds[b][k],sign=k==j?1:-1,dp=sign*NORMAL.density(t)*(cdf((au-rho*t)/Math.sqrt(1-rho*rho))-cdf((al-rho*t)/Math.sqrt(1-rho*rho)));crossB[k]+=derivative*dp/probability;}}
            if(!(information>1e-10)||!Double.isFinite(information))throw new IllegalArgumentException("Ordinal pair information is singular.");double mean=0;for(int row=0;row<n;row++){double influence=score[codes[row][a]][codes[row][b]];for(int k=0;k<ka-1;k++)influence-=crossA[k]*((codes[row][a]<=k?1:0)-cdf(thresholds[a][k]))/NORMAL.density(thresholds[a][k]);for(int k=0;k<kb-1;k++)influence-=crossB[k]*((codes[row][b]<=k?1:0)-cdf(thresholds[b][k]))/NORMAL.density(thresholds[b][k]);influences[row][column]=influence/information;mean+=influences[row][column]/n;}for(var row:influences)row[column]-=mean;
        }
        double[][] gamma=new double[moments][moments];for(var row:influences)for(int i=0;i<moments;i++)for(int j=0;j<=i;j++)gamma[i][j]+=row[i]*row[j]/n;for(int i=0;i<moments;i++)for(int j=0;j<i;j++)gamma[j][i]=gamma[i][j];if(Matrices.minEigenvalue(correlation)<=1e-8)warnings.add("The pairwise polychoric correlation matrix is not positive definite. No repair was applied; inspect pairwise compatibility and the structured ordinal-model fit.");warnings.add("Ordered labels define threshold order; numerical category codes are not treated as continuous distances. Pairwise latent-response correlations assume bivariate-normal response margins.");warnings.add("Moment covariance uses individual-case influence with estimated marginal thresholds accounted for. Sparse categories, distribution misspecification and small samples can undermine asymptotic inference.");return new Fit(n,names,levels,thresholds,pairs,correlation,gamma,warnings);
    }
    @FunctionalInterface private interface Scalar{double value(double x);}
    private record UnivariateFunction(Scalar function){double value(double x){return function.value(x);}}
    static double pairLoss(int[][] counts,double[] a,double[] b,double rho){double loss=0;for(int i=0;i<counts.length;i++)for(int j=0;j<counts[i].length;j++)if(counts[i][j]>0){double probability=cell(bound(a,i-1),bound(a,i),bound(b,j-1),bound(b,j),rho);if(!(probability>0))return Double.POSITIVE_INFINITY;loss-=counts[i][j]*Math.log(probability);}return loss;}
    static double bound(double[] t,int index){return index<0?Double.NEGATIVE_INFINITY:index>=t.length?Double.POSITIVE_INFINITY:t[index];}
    static double cdf(double value){return NORMAL.cumulativeProbability(value);}
    static double density(double a,double b,double rho){if(!Double.isFinite(a)||!Double.isFinite(b))return 0;double denominator=1-rho*rho;return Math.exp(-(a*a-2*rho*a*b+b*b)/(2*denominator))/(2*Math.PI*Math.sqrt(denominator));}
    static double bivariate(double a,double b,double rho){if(a==Double.NEGATIVE_INFINITY||b==Double.NEGATIVE_INFINITY)return 0;if(a==Double.POSITIVE_INFINITY)return cdf(b);if(b==Double.POSITIVE_INFINITY)return cdf(a);if(Math.abs(rho)<1e-15)return cdf(a)*cdf(b);double sum=0,half=rho/2;for(int i=0;i<QUADRATURE.getNumberOfPoints();i++){double t=half*(QUADRATURE.getPoint(i)+1);sum+=QUADRATURE.getWeight(i)*density(a,b,t);}double result=cdf(a)*cdf(b)+half*sum;if(result< -1e-12||result>1+1e-12)throw new IllegalArgumentException("Bivariate normal integration exceeded probability bounds.");return Math.max(0,Math.min(1,result));}
    static double cell(double al,double au,double bl,double bu,double rho){double probability=bivariate(au,bu,rho)-bivariate(al,bu,rho)-bivariate(au,bl,rho)+bivariate(al,bl,rho);if(probability< -1e-12)throw new IllegalArgumentException("Negative ordinal cell probability beyond numerical tolerance.");return Math.max(0,probability);}
}
